namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and civilizations." },
            new() { Id = 6, Code = "BIOL", Name = "Biology", Description = "Study of living organisms and life processes." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers in top-tier conferences and holds two patents in neural network architectures.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Computer Science", Bio = "Dr. Martinez focuses on distributed systems and cloud computing. He spent 10 years in industry at major tech companies before joining academia.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Dr. Sarah Thompson", Title = "Professor of Mathematics", Bio = "Dr. Thompson is an expert in abstract algebra and number theory. She has received the Distinguished Teaching Award three times.", Email = "sthompson@university.edu" },
            new() { Id = 4, Name = "Dr. James Wilson", Title = "Associate Professor of Physics", Bio = "Dr. Wilson researches quantum mechanics and particle physics. He previously worked at CERN on the Large Hadron Collider project.", Email = "jwilson@university.edu" },
            new() { Id = 5, Name = "Prof. Emily Davis", Title = "Professor of English", Bio = "Prof. Davis is a literary scholar specializing in 19th-century American literature. She has authored three critically acclaimed books on the works of Emily Dickinson.", Email = "edavis@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Associate Professor of History", Bio = "Dr. Brown is a historian of the modern Middle East with expertise in Ottoman Empire studies. He regularly contributes to the Journal of World History.", Email = "mbrown@university.edu" },
            new() { Id = 7, Name = "Dr. Lisa Park", Title = "Professor of Biology", Bio = "Dr. Park is a molecular biologist studying gene expression in cancer cells. Her lab has received continuous NIH funding for the past 15 years.", Email = "lpark@university.edu" },
            new() { Id = 8, Name = "Dr. David Kim", Title = "Associate Professor of Mathematics", Bio = "Dr. Kim specializes in applied mathematics and numerical analysis. He develops computational methods used in climate modeling.", Email = "dkim@university.edu" },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering fundamental concepts including algorithms, data structures, software engineering, and the social impact of computing. Students will complete programming assignments in Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Includes complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 2, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 350", Title = "Artificial Intelligence", Description = "Introduction to the theory and practice of artificial intelligence. Topics include search, knowledge representation, planning, machine learning, natural language processing, and computer vision.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Building 110", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 42 },
            new() { Id = 4, Code = "CS 310", Title = "Distributed Systems", Description = "Principles and paradigms of distributed computing systems. Topics include communication, processes, naming, synchronization, consistency, replication, fault tolerance, and security in distributed environments.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Tech Building 215", DepartmentId = 1, InstructorId = 2, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus. Topics include limits, continuity, derivatives of algebraic and transcendental functions, applications of derivatives, and an introduction to integration.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 101", DepartmentId = 2, InstructorId = 3, IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Systems of linear equations, matrices, determinants, vector spaces, linear transformations, eigenvalues and eigenvectors, and applications to geometry and data science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Building 203", DepartmentId = 2, InstructorId = 8, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 65 },
            new() { Id = 7, Code = "MATH 310", Title = "Abstract Algebra", Description = "Introduction to algebraic structures including groups, rings, and fields. Topics include homomorphisms, quotient structures, polynomial rings, and Galois theory.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Math Building 305", DepartmentId = 2, InstructorId = 3, IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 22 },

            // Physics
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Introductory physics covering mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments demonstrating fundamental physical principles.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM, Lab: Thu 2:00–4:50 PM", Location = "Physics Building 100", DepartmentId = 3, InstructorId = 4, IsFeatured = true, MaxEnrollment = 100, CurrentEnrollment = 88 },
            new() { Id = 9, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave-particle duality, the Schrödinger equation, angular momentum, spin, and applications to atomic and molecular systems.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Physics Building 210", DepartmentId = 3, InstructorId = 4, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 25 },

            // English
            new() { Id = 10, Code = "ENG 101", Title = "Composition and Rhetoric", Description = "Develop college-level writing skills through analysis of rhetorical strategies, argumentative writing, research methods, and critical reading of diverse texts.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Humanities Hall 105", DepartmentId = 4, InstructorId = 5, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 11, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Examines major authors, movements, and themes in the context of American cultural and social history.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Humanities Hall 210", DepartmentId = 4, InstructorId = 5, IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 30 },

            // History
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the late medieval period. Examines political, social, economic, and cultural developments across diverse global regions.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Liberal Arts 120", DepartmentId = 5, InstructorId = 6, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 60 },
            new() { Id = 13, Code = "HIST 330", Title = "History of the Modern Middle East", Description = "Examines the political, social, and cultural history of the Middle East from the decline of the Ottoman Empire to the present day, including nationalism, oil politics, and regional conflicts.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Liberal Arts 205", DepartmentId = 5, InstructorId = 6, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 28 },

            // Biology
            new() { Id = 14, Code = "BIOL 101", Title = "Introduction to Biology", Description = "Foundational course covering cell biology, genetics, evolution, ecology, and organismal biology. Includes weekly laboratory sessions with microscopy and experimental design.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM, Lab: Tue 1:00–3:50 PM", Location = "Life Sciences 100", DepartmentId = 6, InstructorId = 7, IsFeatured = true, MaxEnrollment = 100, CurrentEnrollment = 90 },
            new() { Id = 15, Code = "BIOL 310", Title = "Molecular Biology", Description = "Study of biological processes at the molecular level, including DNA replication, transcription, translation, gene regulation, and modern techniques in molecular biology and genomics.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Life Sciences 301", DepartmentId = 6, InstructorId = 7, IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 30 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null, int? minCredits = null, int? maxCredits = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (minCredits.HasValue)
        {
            query = query.Where(c => c.Credits >= minCredits.Value);
        }

        if (maxCredits.HasValue)
        {
            query = query.Where(c => c.Credits <= maxCredits.Value);
        }

        return query.OrderBy(c => c.Code).ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public Department? GetDepartmentForCourse(int courseId)
    {
        var course = GetCourse(courseId);
        return course is null ? null : GetDepartment(course.DepartmentId);
    }

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

