+            new() { Id = 13, Code = "HIST 330", Title = "History of the Modern Middle East", Description = "Examines the political, social, and cultural history of the Middle East from the decline of the Ottoman Empire to the present day, including nationalism, oil politics, and regional conflicts.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Liberal Arts 205", DepartmentId = 5, InstructorId = 6, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 28 },
+
