@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

@if (Course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="courses" class="btn btn-primary">Back to Course List</a>
}
else
{
    <PageTitle>@Course.Code — @Course.Title</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="courses?departmentId=@Department?.Id">@Department?.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@Course.Code</li>
        </ol>
    </nav>

    <h1>@Course.Code — @Course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@Course.Description</p>

            <h4 class="mt-4">Schedule &amp; Location</h4>
            <dl class="row">
                <dt class="col-sm-3">Schedule</dt>
                <dd class="col-sm-9">@Course.Schedule</dd>
                <dt class="col-sm-3">Location</dt>
                <dd class="col-sm-9">@Course.Location</dd>
            </dl>

            @if (Instructor is not null)
            {
                <h4 class="mt-4">Instructor</h4>
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@Instructor.Name</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@Instructor.Title</h6>
                        <p class="card-text">@Instructor.Bio</p>
                        <p class="card-text"><small class="text-muted">📧 @Instructor.Email</small></p>
                    </div>
                </div>
            }
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-header">Course Details</div>
                <ul class="list-group list-group-flush">
                    <li class="list-group-item"><strong>Credits:</strong> @Course.Credits</li>
                    <li class="list-group-item"><strong>Department:</strong> @Department?.Name (@Department?.Code)</li>
                    <li class="list-group-item">
                        <strong>Enrollment:</strong> @Course.CurrentEnrollment / @Course.MaxEnrollment
                        @if (Course.CurrentEnrollment >= Course.MaxEnrollment)
                        {
                            <span class="badge bg-danger ms-1">Full</span>
                        }
                        else
                        {
                            <span class="badge bg-success ms-1">Open</span>
                        }
                    </li>
                </ul>
                <div class="card-body">
                    <a href="enroll?courseId=@Course.Id" class="btn btn-primary w-100">Request Enrollment</a>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? Course { get; set; }
    private Department? Department { get; set; }
    private Instructor? Instructor { get; set; }

    protected override void OnInitialized()
    {
        Course = CatalogService.GetCourse(Id);
        if (Course is not null)
        {
            Department = CatalogService.GetDepartment(Course.DepartmentId);
            Instructor = CatalogService.GetInstructor(Course.InstructorId);
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Complete the form below to submit an enrollment request. You will receive confirmation via your university email.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted</h4>
        <p>Your enrollment request for <strong>@SelectedCourseTitle</strong> has been submitted successfully.</p>
        <hr />
        <p class="mb-0">
            <a href="enroll" class="alert-link">Submit another request</a> ·
            <a href="courses" class="alert-link">Browse courses</a>
        </p>
    </div>
}
else
{
    <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
        <AntiforgeryToken />

        <div class="row">
            <div class="col-md-6">
                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                           value="@Model.StudentName" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                           value="@Model.StudentId" required placeholder="e.g., S12345678" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select class="form-select" id="courseId" name="Model.CourseId" required>
                        <option value="0">— Select a course —</option>
                        @foreach (var course in Courses)
                        {
                            if (course.Id == Model.CourseId)
                            {
                                <option value="@course.Id" selected>@course.Code — @course.Title (@course.Credits cr)</option>
                            }
                            else
                            {
                                <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                            }
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </div>
        </div>
    </form>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> Courses { get; set; } = new();
    private bool Submitted { get; set; }
    private string SelectedCourseTitle { get; set; } = string.Empty;

    protected override void OnInitialized()
    {
        Courses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Model.StudentName) ||
            string.IsNullOrWhiteSpace(Model.StudentId) ||
            Model.CourseId <= 0)
        {
            return;
        }

        var course = CatalogService.GetCourse(Model.CourseId);
        SelectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";

        CatalogService.SubmitEnrollmentRequest(new EnrollmentRequest
        {
            StudentName = Model.StudentName,
            StudentId = Model.StudentId,
            CourseId = Model.CourseId,
        });

        Submitted = true;
    }
}

